const input=$input.first()?.json||{};
const text=v=>String(v??'').normalize('NFKC').trim();
const collection=text(input.qdrantCollection);
if(!/^[A-Za-z0-9._-]{1,240}$/.test(collection)) throw new Error('Qdrant loader: invalid collection');
if(!/^tgactor_[a-f0-9]{64}$/.test(text(input.principalKey))||!/^tenant_actor_[a-f0-9]{32}$/.test(text(input.tenantId))) throw new Error('Qdrant loader: immutable identity required');
const arr=Array.isArray(input.qdrantDirectItems)&&input.qdrantDirectItems.length?input.qdrantDirectItems:[{sourceText:input.sourceText||'',sourceTitle:input.sourceTitle||'',pointId:''}];
const hash128=s=>{const x=String(s).normalize('NFKC');let a=0xdeadbeef^x.length,b=0x41c6ce57^x.length,c=0xc0decafe^x.length,d=0x9e3779b9^x.length;for(let i=0;i<x.length;i++){const q=x.charCodeAt(i);a=Math.imul(a^q,2654435761);b=Math.imul(b^q,1597334677);c=Math.imul(c^q,2246822507);d=Math.imul(d^q,3266489909);}return[a,b,c,d].map(n=>(n>>>0).toString(16).padStart(8,'0')).join('')};
const toUuid=s=>{const h=hash128(s);return `${h.slice(0,8)}-${h.slice(8,12)}-4${h.slice(13,16)}-a${h.slice(17,20)}-${h.slice(20,32)}`};
const canonical=v=>{if(Array.isArray(v))return '['+v.map(canonical).join(',')+']';if(v&&typeof v==='object')return '{'+Object.keys(v).sort().map(k=>JSON.stringify(k)+':'+canonical(v[k])).join(',')+'}';return JSON.stringify(v)};
const items=arr.map((raw,i)=>{
 const envelope=raw&&typeof raw==='object'&&!Array.isArray(raw)?raw:{};
 const nested=envelope.item&&typeof envelope.item==='object'&&!Array.isArray(envelope.item)?envelope.item:{};
 const explicitPayload=envelope.payload&&typeof envelope.payload==='object'&&!Array.isArray(envelope.payload)?envelope.payload:{};
 const sourceText=text(envelope.sourceText||nested.sourceText||explicitPayload.sourceText||nested.content||nested.fact||nested.text||nested.statement||nested.question||nested.answerText||explicitPayload.content||explicitPayload.fact||input.sourceText);
 if(!sourceText) throw new Error(`Qdrant loader: item ${i} has no semantic text`);
 const payload={...nested,...explicitPayload};
 for(const [k,v] of Object.entries(envelope)) if(!['item','payload','vector','sourceText','pointId','id','index','type'].includes(k)&&payload[k]===undefined) payload[k]=v;
 delete payload.vector; delete payload.item;
 if(input.universalMemoryMode===true&& !text(payload.pointType)) payload.pointType='knowledge_item';
 const explicitId=text(envelope.pointId||envelope.id||nested.qdrantPointId||nested.stableQdrantPointId||nested.pointId||explicitPayload.pointId);
 const pointId=explicitId||toUuid(`${input.principalKey}|${text(payload.knowledgeId||payload.semanticKey||payload.predicateKey||input.uploadId)}|${i}|${sourceText}`);
 if(!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(pointId)&&!/^[0-9]+$/.test(pointId)) throw new Error(`Qdrant loader: invalid point id ${pointId}`);
 const hashPayload={...payload}; for(const k of ['updatedAt','createdAt','lastSeenAt','observedAt','loadedAt']) delete hashPayload[k];
 const contentHash=hash128(sourceText+'|'+canonical(hashPayload));
 return {pointId,sourceText,payload:{...payload,pointId,principalKey:input.principalKey,tenantId:input.tenantId,memoryTenantId:input.memoryTenantId||input.tenantId,userId:input.userId||'',sourceTitle:envelope.sourceTitle||nested.sourceTitle||input.sourceTitle||'',sourceText,contentHash,loaderContractVersion:'chelsea_qdrant_loader_v2_0',payloadShape:text(payload.payloadShape)|| (input.universalMemoryMode===true?'chelsea_qdrant_memory_point_v2':'chelsea_qdrant_direct_point_v2')}};
});
const instructionItems=items.filter(x=>text(x.payload.memoryKind).toLowerCase()==='triggered_instruction');
for(const x of instructionItems){if(!text(x.payload.instructionId)||!/^([a-f0-9]{64}|sha256:[a-f0-9]{64})$/i.test(text(x.payload.assistantArtifactHash))||!text(x.payload.sourceAnswerMessageId))throw new Error('Qdrant loader: triggered instruction provenance incomplete');}
return [{json:{...input,qdrantCollection:collection,preparedItems:items,preparedFileCount:items.length,pointIds:items.map(x=>x.pointId),embeddingRequestBody:{model:$env.CHELSEA_OPENAI_EMBEDDING_MODEL||'text-embedding-3-small',input:items.map(x=>x.sourceText)},skipExistingQdrantPoints:input.skipExistingQdrantPoints===true,reindexChangedQdrantPoints:input.reindexChangedQdrantPoints!==false,instructionExpectedCount:instructionItems.length}}];

const prepared=$('Code | Validate and Prepare Qdrant Items | QdrantLoader').first().json;
const existingResp=$('Call | Qdrant | Retrieve Existing Points | QdrantLoader').first().json||{};
const embedResp=$('Call | OpenAI | Embed Qdrant Items | QdrantLoader').first().json||{};
if(embedResp.error) throw new Error(`Qdrant loader embedding failed: ${embedResp.error.message||'unknown'}`);
const vectors=Array.isArray(embedResp.data)?embedResp.data.slice().sort((a,b)=>Number(a.index)-Number(b.index)).map(x=>x.embedding):[];
if(vectors.length!==prepared.preparedItems.length||vectors.some(v=>!Array.isArray(v)||!v.length)) throw new Error('Qdrant loader: embedding count mismatch');
const existingRows=Array.isArray(existingResp.result)?existingResp.result:[];const existing=new Map(existingRows.map(x=>[String(x.id),x]));
const selected=[],skipped=[];
prepared.preparedItems.forEach((item,i)=>{const old=existing.get(String(item.pointId));const same=old&&String(old.payload?.contentHash||'')===String(item.payload.contentHash);if(prepared.skipExistingQdrantPoints&&old&&(!prepared.reindexChangedQdrantPoints||same)){skipped.push(item.pointId);}else selected.push({id:item.pointId,vector:vectors[i],payload:item.payload});});
return [{json:{...prepared,selectedPoints:selected,selectedForIndexingCount:selected.length,skippedExistingQdrantPointCount:skipped.length,skippedExamples:skipped.slice(0,20),upsertBody:{points:selected}}}];
